    # First try to read as if it's actually a valid zip file
    with zipfile.ZipFile(CsvPath, 'r') as z:
        # List contents
        print("Zip file contents:")
        print(z.namelist())
        # If it's a valid zip with a CSV inside, extract and read
        if len(z.namelist()) > 0:
            csv_file = z.namelist()[0]
            df = pd.read_csv(z.open(csv_file))
        else:
            raise Exception("Empty zip file")
except Exception as e:
    print(f"Not a valid zip file: {e}")
    # Try reading as CSV with compression='zip' parameter
    try:
        df = pd.read_csv(CsvPath, compression='zip')
        print("Read successfully with compression='zip'")
